import React, { useEffect, useRef, useState } from "react";
import { useForm, Controller, SubmitHandler } from "react-hook-form";
import { yupResolver } from "@hookform/resolvers/yup";
import * as yup from "yup";
import {
  TextField,
  Button,
  Box,
  Typography,
  MenuItem,
  Collapse,
  InputAdornment,
} from "@mui/material";
import { useTranslation } from "react-i18next";
import { db } from "../../firebaseConfig";
import { collection, addDoc, Timestamp } from "firebase/firestore";
import emailjs from "@emailjs/browser";
import ButtonComponent from "./buttons";
import data from "../data/data.json";

const phoneRegExp = /^\d{3} \d{3}-\d{4}$/;

const schema: yup.ObjectSchema<FormData> = yup.object({
  category: yup.string(),
  name: yup.string(),
  address: yup.string(),
  email: yup.string().email("Invalid email").required("Email is required"),
  telephone: yup
    .string()
    .matches(phoneRegExp, "Invalid phone number")
    .required("Telephone is required"),
  productInterest: yup
    .string()
    .min(6, "Minimum 6 characters")
    .required("Product interest is required"),
}) as yup.ObjectSchema<FormData>;

type FormData = {
  category: string;
  name: string;
  address: string;
  email: string;
  telephone: string;
  productInterest: string;
};

export default function PartnersForm() {
  const [sending, setSending] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  const [categoryOpen, setCategoryOpen] = useState(false);
  const categoryWrapRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    if (!categoryOpen) return;
    const handleClickOutside = (event: MouseEvent) => {
      const wrap = categoryWrapRef.current;
      if (wrap && !wrap.contains(event.target as Node)) {
        setCategoryOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, [categoryOpen]);

  const { t } = useTranslation();
  const categoryOptions = Array.isArray(data.partnersForm)
    ? data.partnersForm
    : [];

  const {
    control,
    handleSubmit,
    reset,
    formState: { errors, isValid },
  } = useForm<FormData>({
    resolver: yupResolver(schema),
    mode: "onChange",
    defaultValues: {
      category: "",
      name: "",
      address: "",
      email: "",
      telephone: "",
      productInterest: "",
    },
  });

  const onSubmit: SubmitHandler<FormData> = async (data) => {
    setSending(true);
    try {
      await addDoc(collection(db, "partnersForm"), {
        ...data,
        createdAt: Timestamp.now(),
      });

      // const serviceId = process.env.GATSBY_EMAILJS_SERVICE_ID;
      // const templateId = process.env.GATSBY_EMAILJS_TEMPLATE_ID;
      // const publicKey = process.env.GATSBY_EMAILJS_PUBLIC_KEY;

      // const serviceId = "service_60iafie";
      // const templateId = "template_34muhgj";
      // const publicKey = "r2514o3SW3UyPR7Pl";

      // if (!serviceId || !templateId || !publicKey) {
      //   console.error("Missing EmailJS environment variables");
      //   setSending(false);
      //   return;
      // }

      // await emailjs.send(
      //   serviceId,
      //   templateId,
      //   {
      //     category: data.category,
      //     name: data.name,
      //     address: data.address,
      //     email: data.email,
      //     telephone: data.telephone,
      //     productInterest: data.productInterest,
      //   },
      //   publicKey
      // );

      reset();
      setSubmitted(true);
    } catch (error) {
      console.error("Error submitting form:", error);
    } finally {
      setSending(false);
    }
  };

  return (
    <Box
      component="form"
      onSubmit={handleSubmit(onSubmit)}
      className="w-full sm:w-[400px]"
    >
      {submitted ? (
        <Box className="flex flex-col items-center mt-12 p-4 text-center">
          <Typography
            variant="h6"
            className="text-LightGrayText body-mob sm:body mb-2"
          >
            {t("partners.form.thankYou") || "Thank you for your message!"}
          </Typography>
          <Typography className="text-LightGrayText body-mob sm:body mb-4">
            {t("partners.form.confirmation") ||
              "We will get back to you shortly."}
          </Typography>
          <Button
            onClick={() => {
              reset();
              setSubmitted(false);
            }}
            className="w-full border 
              !backdrop-blur-md 
              rounded-lg py-4 px-4 body-4
              border-Tofu hover:border-Oatmeal 
              bg-white/10 hover:bg-white/20 
              active:border-DeepSea active:text-DeepSea"
          >
            <span className="text-DarkGreen body-mob sm:body">
              {t("partners.form.backToForm") || "Back to Form"}
            </span>
          </Button>
        </Box>
      ) : (
        <>
          <div className="body-mob sm:body mb-6 text-white">
            {t("partners.form.subtitle")}
          </div>

          {/* Category */}
          <div ref={categoryWrapRef} className="w-full">
            <Controller
              name="category"
              control={control}
              render={({
                field: { onChange, onBlur, value, ref, ...field },
              }) => (
                <>
                  <TextField
                    {...field}
                    inputRef={ref}
                    fullWidth
                    margin="dense"
                    variant="outlined"
                    // label={t("partners.form.category.label") || "Category"}
                                    InputLabelProps={{ shrink: false }} 
                label=" "
                hiddenLabel
                    className="body-mob sm:body text-LightGrayText"
                    onClick={() => setCategoryOpen((open) => !open)}
                    onBlur={onBlur}
                    onKeyDown={(event) => {
                      if (event.key === "Enter" || event.key === " ") {
                        event.preventDefault();
                        setCategoryOpen((open) => !open);
                      }
                      if (event.key === "Escape") {
                        setCategoryOpen(false);
                      }
                    }}
                    value={
                      value
                        ? t(`partners.form.category.options.${value}`) ||
                          String(value)
                        : ""
                    }
                    placeholder={
                      t("partners.form.category.placeholder") ||
                      "Select a category"
                    }
                    InputProps={{
                      readOnly: true,
                      endAdornment: (
                        <InputAdornment position="end" className="!text-LightGrayText">
                          <span aria-hidden="true">
                            {categoryOpen ? "-" : "+"}
                          </span>
                        </InputAdornment>
                      ),
                    }}
                    sx={{
                      // ✅ estilo “glass” del input (para que combine con el menú)
                      "& .MuiOutlinedInput-root": {
                        borderRadius: "4px",
                        backgroundColor: "rgba(255,255,255,0.06)",
                        backdropFilter: "blur(10px)",
                        "& fieldset": { borderColor: "rgba(255,255,255,0.25)" },
                        "&:hover fieldset": {
                          borderColor: "rgba(255,255,255,0.40)",
                        },
                        "&.Mui-focused fieldset": {
                          borderColor: "rgba(255,255,255,0.55)",
                        },
                      },
                      "& .MuiSelect-select": {
                        paddingTop: "14px",
                        paddingBottom: "14px",
                      },
                    }}
                  />
                  <Collapse in={categoryOpen} timeout="auto" unmountOnExit>
                    <Box
                      sx={{
                        mt: 1,
                        width: "100%",
                        maxHeight: 280,
                        borderRadius: "4px",
                        border: "1px solid #FFFF00",
                        backgroundColor: "rgba(255,255,255,0.08)",
                        backdropFilter: "blur(12px)",
                        boxShadow: "none",
                        overflow: "hidden",
                      }}
                    >
                      {categoryOptions.map((option) => (
                        <MenuItem
                          key={option}
                          selected={value === option}
                          onClick={() => {
                            onChange(option);
                            setCategoryOpen(false);
                          }}
                          sx={{
                            fontSize: 22,
                            fontWeight: 300,
                            py: 1,
                            color: "rgba(255,255,255,0.6)",
                            "&.Mui-selected": {
                              backgroundColor: "rgba(255,255,255,0.12)",
                            },
                            "&.Mui-selected:hover": {
                              backgroundColor: "rgba(255,255,255,0.16)",
                            },
                          }}
                        >
                          {t(`partners.form.category.options.${option}`) ||
                            option}
                        </MenuItem>
                      ))}
                    </Box>
                  </Collapse>
                </>
              )}
            />
          </div>

          {/* Name */}
          <Controller
            name="name"
            control={control}
            render={({ field }) => (
              <TextField
                {...field}
                // label={t("partners.form.name.label") || "Name"}
                                InputLabelProps={{ shrink: false }} 
                label=" "
                
                placeholder={t("partners.form.name.placeholder") || "Your name"}
                fullWidth
                margin="dense"
                variant="outlined"
                className="body-mob sm:body text-LightGrayText"
              />
            )}
          />

          {/* Address */}
          <Controller
            name="address"
            control={control}
            render={({ field }) => (
              <TextField
                {...field}
                // label={t("partners.form.address.label") || "Address"}
                                InputLabelProps={{ shrink: false }} 
                label=" "
                hiddenLabel
                placeholder={
                  t("partners.form.address.placeholder") || "Your address"
                }
                fullWidth
                margin="dense"
                variant="outlined"
                
                className="body-mob sm:body text-LightGrayText"
              />
            )}
          />

          {/* Email */}
          <Controller
            name="email"
            control={control}
            render={({ field }) => (
              <TextField
                {...field}
                // label={t("partners.form.email.label") || "Email"}
                                InputLabelProps={{ shrink: false }} 
                label=" "
                hiddenLabel
                placeholder={
                  t("partners.form.email.placeholder") || "name@email.com"
                }
                error={!!errors.email}
                fullWidth
                margin="dense"
                variant="outlined"
                className="body-4 bg-DeepSea/10"
                helperText={errors.email?.message || ""}
              />
            )}
          />

          {/* Telephone */}
          <Controller
            name="telephone"
            control={control}
            render={({ field: { onChange, value, ...field } }) => (
              <TextField
                {...field}
                value={value}
                onChange={(e) => {
                  const digits = e.target.value.replace(/\D/g, "").slice(0, 10);
                  const part1 = digits.slice(0, 3);
                  const part2 = digits.slice(3, 6);
                  const part3 = digits.slice(6, 10);
                  const formatted = part3
                    ? `${part1} ${part2}-${part3}`
                    : part2
                    ? `${part1} ${part2}`
                    : part1;
                  onChange(formatted);
                }}
                // label={t("partners.form.telephone.label") || "Telephone"}
                                InputLabelProps={{ shrink: false }} 
                label=" "
                hiddenLabel
                placeholder={
                  t("partners.form.telephone.placeholder") || "123 456-7890"
                }
                error={!!errors.telephone}
                fullWidth
                margin="dense"
                variant="outlined"
                className="body-4 bg-DeepSea/10"
                helperText={errors.telephone?.message || ""}
              />
            )}
          />

          {/* Product Interest */}
          <Controller
            name="productInterest"
            control={control}
            render={({ field }) => (
              <TextField
                {...field}
                // label={
                //   t("partners.form.productInterest.label") ||
                //   "What's your product interest"
                // }
                InputLabelProps={{ shrink: false }} 
                label=" "
                placeholder={
                  t("partners.form.productInterest.placeholder") ||
                  "Tell us about your product interest"
                }
                error={!!errors.productInterest}
                fullWidth
                margin="dense"
                variant="outlined"
                multiline={true}
                rows={4}
                className="body-4 bg-DeepSea/10"
                helperText={errors.productInterest?.message || ""}
              />
            )}
          />

          <div className="mt-2 text-LightGrayText">
            <ButtonComponent
              isDisabled={!isValid || sending}
              isSubmit={true}
              sending={sending}
              labelKey="partners.form.send"
            />
          </div>
        </>
      )}
    </Box>
  );
}
